(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.27)*16 + Math.sin(x*0.016+t*0.33)*11;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8 + Math.cos((x-y)*0.012-t*0.18)*6;
  const w2y = Math.cos((x-y)*0.011+t*0.17)*7 + Math.sin((x+y)*0.009-t*0.14)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+4)*55, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75+1)*65, 0.085, 1.8],
    [200+Math.sin(t*0.25+1)*130, 220+Math.cos(t*0.45+3)*70, 0.075, 2.4]
  ];
  let aS=0, iS=0, hS=0;
  for(const [sX,sY,f,sp] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=Math.sin(d*f-t*sp);
    aS+=w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hS+=Math.sin(d*f*1.3-t*sp*0.8+3.0);
  }
  const act=aS/9, inh=iS/9, harm=hS/9;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const micro=Math.sin(sx*0.3+t*1.5)*Math.sin(sy*0.3-t*1.2)*0.15;
  const reaction=Math.tanh((act-inh*0.7+harm*0.25+bg*0.3+spiral+micro)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const nx=Math.sin(sx*0.08+t*0.5), ny=Math.sin(sy*0.08-t*0.4);
  const flow=Math.sin(nx*3+ny*2+dist*0.03-t*0.8)*0.2;
  const blend=reaction*0.6+cell*0.2+flow*0.2;
  const v=blend*0.5+0.5;
  const edge=Math.abs(reaction);
  const glow=edge>0.75?(edge-0.75)*4:0;
  const pal=[
    [5,12,55],[12,45,95],[18,85,125],[30,135,140],[120,170,130],
    [195,185,80],[220,140,60],[200,85,55],[140,40,55],[60,18,45],[5,12,55]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.2+glow*0.15;
  const eMul=1.0+glow*0.25;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*eMul+glow*20)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*eMul+glow*15)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*eMul+glow*25)|0)
  ];
}
